import { memo, useCallback, useMemo, useRef, useState } from 'react';

import { useIntl } from 'react-intl';

import type {
  IIconButtonProps,
  IIconProps,
  IStackProps,
  IXStackProps,
} from '@onekeyhq/components';
import { IconButton } from '@onekeyhq/components';
import { ETranslations } from '@onekeyhq/shared/src/locale';
import { defaultLogger } from '@onekeyhq/shared/src/logger/logger';
import type { EWatchlistFrom } from '@onekeyhq/shared/src/logger/scopes/dex';
import { travelModeManager } from '@onekeyhq/shared/src/travelMode';
import { getMarketWatchlistKey } from '@onekeyhq/shared/src/utils/marketWatchlistIdentity';

import { useMarketWatchListV2Atom } from '../../../states/jotai/contexts/marketV2';
import { MarketTestIDs } from '../testIDs';

import { useWatchListV2Action } from './watchListHooksV2';

import type { IMarketStarV2Props } from './MarketStarV2.types';

export const useStarV2Checked = ({
  assetId,
  stockId,
  chainId,
  contractAddress,
  from,
  tokenSymbol,
  isNative = false,
}: {
  assetId?: string;
  stockId?: string;
  chainId: string;
  contractAddress: string;
  from: EWatchlistFrom;
  tokenSymbol?: string;
  isNative?: boolean;
}) => {
  const actions = useWatchListV2Action();
  const [{ data: watchListData, isMounted }] = useMarketWatchListV2Atom();
  const [isMutating, setIsMutating] = useState(false);
  const isMutatingRef = useRef(false);

  // Calculate checked state based on atom data
  const checked = useMemo(() => {
    if (!isMounted || watchListData.length === 0) {
      return false;
    }
    const key = getMarketWatchlistKey({
      chainId,
      contractAddress,
      assetId,
      stockId,
    });
    return watchListData.some((item) => getMarketWatchlistKey(item) === key);
  }, [watchListData, isMounted, chainId, contractAddress, assetId, stockId]);

  const handlePress = useCallback(async () => {
    if (!isMounted || isMutatingRef.current) {
      return;
    }
    isMutatingRef.current = true;
    setIsMutating(true);
    try {
      if (checked) {
        const removed = await actions.removeFromWatchListV2(
          chainId,
          contractAddress,
          { assetId, stockId },
        );
        if (!removed) {
          return;
        }
        defaultLogger.dex.watchlist.dexRemoveFromWatchlist({
          network: chainId,
          tokenSymbol: tokenSymbol || '',
          tokenContract: contractAddress,
          removeFrom: from,
        });
      } else {
        const added = await actions.addIntoWatchListV2([
          {
            chainId: assetId || stockId ? '' : chainId,
            contractAddress: assetId || stockId ? '' : contractAddress,
            isNative,
            assetId,
            stockId,
          },
        ]);
        if (!added) {
          return;
        }
        defaultLogger.dex.watchlist.dexAddToWatchlist({
          network: chainId,
          tokenSymbol: tokenSymbol || '',
          tokenContract: contractAddress,
          addFrom: from,
        });
      }
    } finally {
      isMutatingRef.current = false;
      setIsMutating(false);
    }
  }, [
    actions,
    assetId,
    stockId,
    chainId,
    checked,
    contractAddress,
    from,
    isMounted,
    isNative,
    tokenSymbol,
  ]);

  return useMemo(
    () => ({
      checked,
      disabled: !isMounted || isMutating,
      onPress: handlePress,
    }),
    [checked, handlePress, isMounted, isMutating],
  );
};

function BasicMarketStarV2({
  assetId,
  stockId,
  chainId,
  contractAddress,
  size,
  from,
  tokenSymbol,
  isNative = false,
  customIconSize,
  ...props
}: IMarketStarV2Props) {
  const intl = useIntl();
  const { onPress, checked, disabled } = useStarV2Checked({
    assetId,
    stockId,
    chainId,
    contractAddress,
    from,
    tokenSymbol,
    isNative,
  });
  if (
    travelModeManager.getRuntimeEnvironmentSync().profile.kind === 'travel-mode'
  ) {
    return null;
  }

  return (
    <IconButton
      testID={
        tokenSymbol ? MarketTestIDs.tokenStarButton(tokenSymbol) : undefined
      }
      title={intl.formatMessage({
        id: checked
          ? ETranslations.market_remove_from_favorites
          : ETranslations.market_add_to_favorites,
      })}
      icon={checked ? 'StarSolid' : 'StarOutline'}
      variant="tertiary"
      size={size}
      iconSize={size ? undefined : '$5'}
      iconProps={{
        color: checked ? '$iconActive' : '$iconSubdued',
        ...(customIconSize ? { size: customIconSize } : {}),
      }}
      onPress={onPress}
      disabled={disabled}
      {...(props as IXStackProps)}
    />
  );
}

export const MarketStarV2 = memo(BasicMarketStarV2);

// Perps star hook — checks watchlist by perpsCoin
export const usePerpsStarV2Checked = ({ perpsCoin }: { perpsCoin: string }) => {
  const actions = useWatchListV2Action();
  const [{ data: watchListData, isMounted }] = useMarketWatchListV2Atom();

  const checked = useMemo(() => {
    if (!isMounted || watchListData.length === 0) {
      return false;
    }
    return !!watchListData.find((item) => item.perpsCoin === perpsCoin);
  }, [watchListData, isMounted, perpsCoin]);

  const handlePress = useCallback(() => {
    if (checked) {
      actions.removePerpsFromWatchListV2(perpsCoin);
    } else {
      actions.addPerpsIntoWatchListV2(perpsCoin);
    }
  }, [checked, actions, perpsCoin]);

  return useMemo(
    () => ({
      checked,
      onPress: handlePress,
    }),
    [checked, handlePress],
  );
};

// Perps star button component
function BasicMarketPerpsStarV2({
  perpsCoin,
  size,
  customIconSize,
  ...props
}: {
  perpsCoin: string;
  size?: IIconButtonProps['size'];
  customIconSize?: IIconProps['size'];
} & IStackProps) {
  const intl = useIntl();
  const { onPress, checked } = usePerpsStarV2Checked({ perpsCoin });

  if (
    travelModeManager.getRuntimeEnvironmentSync().profile.kind === 'travel-mode'
  ) {
    return null;
  }

  return (
    <IconButton
      testID="market-intl-icon-btn"
      title={intl.formatMessage({
        id: checked
          ? ETranslations.market_remove_from_favorites
          : ETranslations.market_add_to_favorites,
      })}
      icon={checked ? 'StarSolid' : 'StarOutline'}
      variant="tertiary"
      size={size}
      iconSize={size ? undefined : '$5'}
      iconProps={{
        color: checked ? '$iconActive' : '$iconSubdued',
        ...(customIconSize ? { size: customIconSize } : {}),
      }}
      onPress={onPress}
      {...(props as IXStackProps)}
    />
  );
}

export const MarketPerpsStarV2 = memo(BasicMarketPerpsStarV2);
